function v(t,r){const n=t.length,a=t.filter(e=>e.status==="paid").length,f=t.filter(e=>e.status==="overdue").length,s=n>0?Math.round(a/n*50):25,g=n>0?Math.round(f/n*20):0,u=r.filter(e=>e.status==="active"||e.status==="planning").length,i=u>0?Math.min(30,u*15):10,m=2160*60*60*1e3,M=Date.now(),h=t.some(e=>{const d=e.issueDate||e.createdAt;return d&&M-new Date(String(d)).getTime()<m})?20:5,b=s-g+i+h,o=Math.max(0,Math.min(100,b));let c="Critical",l="#ef4444";return o>=80?(c="Excellent",l="#22c55e"):o>=60?(c="Good",l="#3b82f6"):o>=40&&(c="At Risk",l="#f59e0b"),{score:o,label:c,color:l,breakdown:[{label:"Payments",value:Math.round(s/50*100),color:"#22c55e"},{label:"Engagement",value:Math.round(i/30*100),color:"#3b82f6"},{label:"Recency",value:Math.round(h/20*100),color:"#a855f7"}]}}function p(t,r,n){return v(r.filter(a=>a.clientId===t),n.filter(a=>a.clientId===t))}export{v as a,p as c};
